# rocpiHours: social environment of road transport (Annex I, 2.1): Regulation (EC) 561/2006 as
# amended by Regulation (EU) 2020/1054 (Mobility Package), the AETR agreement and Directive
# 2002/15/EC on the working time of mobile workers.
SEG = "HRS"
CAT = "rocpiHours"
